\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Mode Developer Palette ──
\definecolor{bgdark}{HTML}{0F172A}        % deep navy background
\definecolor{bgcard}{HTML}{1E293B}        % card background
\definecolor{bgcardalt}{HTML}{1A2332}     % alt card bg
\definecolor{electricblue}{HTML}{3B82F6}  % primary accent
\definecolor{amber}{HTML}{F59E0B}         % secondary accent
\definecolor{mint}{HTML}{10B981}          % tertiary accent
\definecolor{coral}{HTML}{F43F5E}         % highlight
\definecolor{purple}{HTML}{8B5CF6}        % special accent
\definecolor{cyan}{HTML}{06B6D4}          % cool accent
\definecolor{textwhite}{HTML}{F1F5F9}     % primary text
\definecolor{textgray}{HTML}{94A3B8}      % secondary text
\definecolor{gridline}{HTML}{334155}      % divider lines
\definecolor{statbg}{HTML}{172033}        % stat banner bg
\definecolor{titlebg}{HTML}{0D1321}       % title bar deep bg

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{electricblue}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Card styles (dark mode left accent stripe) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{electricblue},
    left=12pt, right=10pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={electricblue!40},
    valign=top, drop shadow={opacity=0.35, shadow xshift=1mm, shadow yshift=-1mm},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{amber},
    left=12pt, right=10pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={amber!40},
    valign=top, drop shadow={opacity=0.35, shadow xshift=1mm, shadow yshift=-1mm},
  },
  mintcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{mint},
    left=12pt, right=10pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{mint},
    coltitle=mint, colbacktitle=bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={mint!40},
    valign=top, drop shadow={opacity=0.35, shadow xshift=1mm, shadow yshift=-1mm},
  },
  coralcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={4pt}{0pt}{coral},
    left=12pt, right=10pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{coral},
    coltitle=coral, colbacktitle=bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={coral!40},
    valign=top, drop shadow={opacity=0.35, shadow xshift=1mm, shadow yshift=-1mm},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=electricblue!12!bgdark,
    borderline west={5pt}{0pt}{electricblue},
    left=12pt, right=10pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=electricblue!80!black,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.4, shadow xshift=1mm, shadow yshift=-1mm},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=3mm},
]

% ══════════════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebg, colframe=titlebg, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{electricblue},
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{50}{60}\selectfont\bfseries\color{textwhite} State of Developer Ecosystem 2024}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{amber} Language Wars \& Rising Stars}\\[6pt]
  {\fontsize{18}{22}\selectfont\color{textgray} Based on the JetBrains survey of \textbf{23,262 developers worldwide} $\vert$ Data-driven insights heading into 2025}
}

% ══════════════════════════════════════════════════════
% STAT BANNER
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center,
  borderline south={2pt}{0pt}{gridline},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{bgcard}{\parbox{0.90\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{amber} 61\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray} JavaScript}\vspace{3pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{bgcard}{\parbox{0.90\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{electricblue} 57\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray} Python}\vspace{3pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{bgcard}{\parbox{0.90\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{mint} 12\%\,$\to$\,37\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray} TypeScript Growth}\vspace{3pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{bgcard}{\parbox{0.90\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{coral} 18\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray} Build AI Integrations}\vspace{3pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════
% CENTERPIECE: Language Trends Chart (full width)
% ══════════════════════════════════════════════════════
\posterbox[bluecard, title={Top Programming Languages 2017--2024}
]{name=langtrends, column=1, span=2, between=row5 and row11}{
  \fontsize{22}{28}\selectfont\color{textgray}
  \posterfig{0.98}{figures/language_trends.png}{8-year usage trajectory across 23{,}262 developers. JavaScript plateaus at 61\%, Python surges to 57\%, TypeScript triples from 12\% to 37\%.}
}

% ══════════════════════════════════════════════════════
% LEFT COLUMN: Promise Index
% ══════════════════════════════════════════════════════
\posterbox[mintcard, title={The Promise Index}
]{name=promise, column=1, span=1, between=row11 and row15}{
  \fontsize{22}{28}\selectfont\color{textwhite}
  \posterfig{0.96}{figures/promise_index.png}{JetBrains Language Promise Index: 5-year growth, stability, intent-to-adopt, and user retention.}
  \vspace{2mm}
  \colorbox{mint!15!bgdark}{\parbox{0.94\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{18}{22}\selectfont\color{mint}\bfseries TypeScript (199) signals where the ecosystem is heading}\vspace{3pt}%
  }}
}

% ══════════════════════════════════════════════════════
% RIGHT COLUMN: Databases
% ══════════════════════════════════════════════════════
\posterbox[ambercard, title={Databases: PostgreSQL's Surge}
]{name=databases, column=2, span=1, between=row11 and row15}{
  \fontsize{22}{28}\selectfont\color{textwhite}
  \posterfig{0.96}{figures/databases.png}{PostgreSQL climbs from 32\% to 45\% (2019--2024), closing in on MySQL at 52\%.}
  \vspace{2mm}
  \colorbox{amber!15!bgdark}{\parbox{0.94\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{18}{22}\selectfont\color{amber}\bfseries Open-source databases dominate the ecosystem}\vspace{3pt}%
  }}
}

% ══════════════════════════════════════════════════════
% LEFT: Where Applications Live
% ══════════════════════════════════════════════════════
\posterbox[coralcard, title={Where Applications Live}
]{name=platforms, column=1, span=1, between=row15 and row18}{
  \fontsize{22}{28}\selectfont\color{textwhite}
  \posterfig{0.96}{figures/platforms.png}{Desktop dev (53\%) still surpasses mobile (30\%).}
  \vspace{1mm}
  \colorbox{coral!15!bgdark}{\parbox{0.94\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{17}{21}\selectfont\color{coral}\bfseries Browser (58\%) leads $\vert$ Desktop \textgreater{} Mobile}\vspace{3pt}%
  }}
}

% ══════════════════════════════════════════════════════
% RIGHT: AI Integration + Cloud
% ══════════════════════════════════════════════════════
\posterbox[highlightcard, title={AI in the Developer Workflow}
]{name=aicloud, column=2, span=1, between=row15 and row18}{
  \fontsize{22}{28}\selectfont\color{textwhite}
  \begin{minipage}[t]{0.38\linewidth}
    \centering
    \includegraphics[width=0.92\linewidth]{figures/ai_donut.png}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.58\linewidth}
